import {principles,principleDrawing,contextualConnections,cleanJournal} from './principles.js';
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}}
function remove(key){try{localStorage.removeItem(key);return true;}catch{return false;}}
const menu=$('menu-toggle');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));$('main-nav').classList.toggle('is-open',open);});
$('main-nav').querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');$('main-nav').classList.remove('is-open');}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.setAttribute('aria-expanded','false');$('main-nav').classList.remove('is-open');}});

let studied=read('caisik-atlas-studies-v1',[]);studied=Array.isArray(studied)?studied.filter(x=>principles.some(p=>p.id===x)):[];
let current=0;
$('principle-tabs').innerHTML=principles.map((p,i)=>`<button id="principle-tab-${i}" role="tab" aria-controls="principle-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-principle="${i}"><span>0${i+1}</span>${p.name}</button>`).join('');
function renderProgress(){const connections=contextualConnections(studied);$('learning-progress').textContent=`${connections.length} / 7 reflections explored`;$('connection-list').innerHTML=connections.length?connections.map(x=>`<span class="connection-tag">${esc(x.text)}</span>`).join(''):'After exploring a study, mark your reflection to reveal its related concepts. Every study is open from the start.';}
function showPrinciple(i){current=i;const p=principles[i];document.querySelectorAll('[data-principle]').forEach((b,n)=>{b.setAttribute('aria-selected',String(n===i));b.tabIndex=n===i?0:-1;});$('principle-panel').setAttribute('aria-labelledby',`principle-tab-${i}`);$('principle-panel').innerHTML=`<div class="principle-panel-top"><div><p class="eyebrow">STUDY 0${i+1} / PHILOSOPHICAL CONTEXT</p><h3>${p.name}</h3><p>${p.idea}</p><p class="eyebrow">THE URBAN ANALOGY</p><p>${p.urban}</p></div><div class="principle-art"><div id="principle-drawing">${principleDrawing(i)}</div><label for="principle-control">${p.control}</label><input id="principle-control" type="range" min="0" max="100" value="50"><span class="micro">AN INTERACTIVE VISUAL ANALOGY</span></div></div><div class="principle-exercises"><div><strong>TAKE A QUESTION TO THE STREET</strong><p>${p.reflection}</p></div><div><strong>FIND IT IN YOUR FLOW</strong><p>${p.rap}</p></div></div><button id="mark-study" class="text-button">${studied.includes(p.id)?'Reflection explored ✓':'I explored this reflection →'}</button><span id="study-status" class="micro" role="status"></span>`;$('principle-control').addEventListener('input',e=>{$('principle-drawing').innerHTML=principleDrawing(i,e.target.value);});$('mark-study').addEventListener('click',()=>{if(!studied.includes(p.id))studied.push(p.id);const ok=write('caisik-atlas-studies-v1',studied);$('mark-study').textContent='Reflection explored ✓';$('study-status').textContent=ok?' / SAVED IN THIS BROWSER':' / THIS VISIT ONLY';renderProgress();});}
$('principle-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-principle]');if(b)showPrinciple(Number(b.dataset.principle));});
$('principle-tabs').addEventListener('keydown',e=>{let next=current;if(e.key==='ArrowRight'||e.key==='ArrowDown')next=(current+1)%7;else if(e.key==='ArrowLeft'||e.key==='ArrowUp')next=(current+6)%7;else if(e.key==='Home')next=0;else if(e.key==='End')next=6;else return;e.preventDefault();showPrinciple(next);$(`principle-tab-${next}`).focus();});
$('reset-learning').onclick=()=>{studied=[];const ok=remove('caisik-atlas-studies-v1');renderProgress();showPrinciple(current);$('study-status').textContent=ok?' / PROGRESS CLEARED':' / TAB RESET; DEVICE STORAGE UNAVAILABLE';};showPrinciple(0);renderProgress();

const lensCopy={geometry:['VISIBLE STRUCTURE','Radial divisions, circles and repeated tracery organize the image. This drawing highlights a compositional principle; it is not a reconstruction of a particular window or evidence of a hidden code.'],narrative:['DOCUMENTED CHRISTIAN ICONOGRAPHY','Notre-Dame’s south rose dates to 1260. Its figures include apostles and saints. The cathedral’s account explains a Christian iconographic program, rather than an authenticated alchemical blueprint.'],reading:['CONTEMPORARY ARTISTIC INTERPRETATION','For this experience, the centre becomes an analogy for attention and the surrounding forms for many possible viewpoints. That meaning is our creative proposal. What detail changes when you choose a different centre?']};
function showLens(layer){const spokes=Array.from({length:12},(_,i)=>`<g transform="rotate(${i*30} 250 250)"><ellipse cx="250" cy="147" rx="29" ry="54"/><path d="M250 55V97M250 202V222"/></g>`).join('');$('rose-diagram').innerHTML=`<svg viewBox="0 0 500 500"><g fill="none" stroke="currentColor" stroke-width="1"><circle cx="250" cy="250" r="207" opacity=".22"/><circle cx="250" cy="250" r="195" stroke-dasharray="2 7"/><circle cx="250" cy="250" r="170"/><circle cx="250" cy="250" r="158" opacity=".5"/><g ${layer==='narrative'?'fill="#c5a45d20"':''}>${spokes}</g><circle cx="250" cy="250" r="46"/><circle cx="250" cy="250" r="29" ${layer==='reading'?'fill="#c5a45d40"':''}/><path d="M250 5V45M250 455V495M5 250H45M455 250H495M30 30L470 470M470 30L30 470" opacity=".15"/><path d="M250 70L406 340H94Z" opacity="${layer==='geometry'?'.6':'.12'}"/></g><g fill="currentColor" font-family="monospace" font-size="8"><text x="245" y="25">N</text><text x="475" y="254">E</text><text x="246" y="485">S</text><text x="17" y="254">W</text></g></svg>`;$('lens-note').innerHTML=`<strong>${lensCopy[layer][0]}</strong><p>${lensCopy[layer][1]}</p>`;document.querySelectorAll('[data-lens]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lens===layer)));}document.querySelectorAll('[data-lens]').forEach(b=>b.onclick=()=>showLens(b.dataset.lens));showLens('geometry');

const formats={four:'Four bars: one observed detail, one memory, one contradiction, one new beginning.',sixteen:'Sixteen bars: four to set the scene, four to change the viewpoint, four to follow an association, four to answer the opening.',spoken:'Speak for one minute without chasing rhyme. Let a place speak in the first person.',field:'Record thirty seconds of an allowed public soundscape. Choose a quiet place, avoid private conversations and ask before recording identifiable performers.',sketch:'On paper, turn a word from the street into three letter structures. Build the skeleton before adding extensions.',photo:'Frame a circle, a boundary and a patch of light in one photograph. Respect local photography restrictions and people’s privacy.'};
let promptPlace='the city';
const promptSeeds=['Notice a boundary and what crosses it.','Find one repeated shape and one interruption.','Give an overlooked object its own point of view.','Follow the oldest-looking detail into the present.'];
let promptSeed=0;
$('ug-shuffle').onclick=()=>{promptSeed=(promptSeed+1)%promptSeeds.length;$('ug-prompt').textContent=`${promptPlace=== 'the city'?'From the street.':`From ${promptPlace}.`} ${promptSeeds[promptSeed]} ${formats[$('challenge-type').value]}`;};
$('challenge-type').onchange=()=>{$('ug-prompt').textContent=`${promptPlace=== 'the city'?'Give the city a voice.':`From ${promptPlace}.`} ${formats[$('challenge-type').value]}`;};
window.addEventListener('caisik-challenge',e=>{promptPlace=String(e.detail?.location||'the city');$('challenge-type').value='four';$('ug-prompt').textContent=String(e.detail?.prompt||formats.four);setTimeout(()=>{$('challenge-type').focus({preventScroll:true});$('freestyle').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});},0);});
$('use-in-notebook').onclick=()=>{const currentText=$('journal').value;$('journal').value=cleanJournal(`${currentText}${currentText?'\n\n':''}${$('ug-prompt').textContent}\n\n`);journalChanged();$('fieldnotes').scrollIntoView();$('journal').focus({preventScroll:true});};
let pulseTimer=null,audioContext=null,beat=0;
function stopPulse(){clearInterval(pulseTimer);pulseTimer=null;$('pulse-toggle').textContent='Start pulse';$('pulse-toggle').setAttribute('aria-pressed','false');$('beat-indicator').textContent='● ○ ○ ○';$('beat-indicator').setAttribute('aria-label','Pulse stopped');audioContext?.suspend().catch(()=>{});}
function tick(){if(!audioContext)return;const o=audioContext.createOscillator(),g=audioContext.createGain();o.frequency.value=beat===0?880:440;g.gain.setValueAtTime(.055,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.045);o.connect(g);g.connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+.05);$('beat-indicator').textContent=Array.from({length:4},(_,i)=>i===beat?'●':'○').join(' ');$('beat-indicator').setAttribute('aria-label',`Beat ${beat+1}`);beat=(beat+1)%4;}
async function startPulse(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){$('pulse-toggle').textContent='Audio unavailable';return;}audioContext??=new Audio();await audioContext.resume();beat=0;tick();pulseTimer=setInterval(tick,60000/Number($('bpm').value));$('pulse-toggle').textContent='Stop pulse';$('pulse-toggle').setAttribute('aria-pressed','true');}catch{stopPulse();$('pulse-toggle').textContent='Audio unavailable';}}
$('pulse-toggle').onclick=async()=>{if(pulseTimer){stopPulse();return;}$('pulse-toggle').disabled=true;try{await startPulse();}finally{$('pulse-toggle').disabled=false;}};$('bpm').oninput=()=>{$('bpm-value').textContent=`${$('bpm').value} BPM`;if(pulseTimer){clearInterval(pulseTimer);pulseTimer=setInterval(tick,60000/Number($('bpm').value));}};window.addEventListener('pagehide',stopPulse);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopPulse();});

$('journal').value=cleanJournal(read('caisik-atlas-journal-v1',''));
function journalChanged(){$('journal-count').textContent=`${$('journal').value.length} / 4000`;$('journal-status').textContent='UNSAVED CHANGES / ONLY IN THIS TAB';}
$('journal').addEventListener('input',journalChanged);journalChanged();if($('journal').value)$('journal-status').textContent='LOADED FROM THIS BROWSER';
$('save-journal').onclick=()=>{$('journal-status').textContent=write('caisik-atlas-journal-v1',cleanJournal($('journal').value))?'SAVED ON THIS DEVICE / NO UPLOAD':'STORAGE UNAVAILABLE / EXPORT TO KEEP YOUR NOTE';};
$('clear-journal').onclick=()=>{const ok=remove('caisik-atlas-journal-v1');$('journal').value='';journalChanged();$('journal-status').textContent=ok?'NOTE CLEARED FROM TAB AND DEVICE':'TAB CLEARED / DEVICE STORAGE COULD NOT BE ACCESSED';};
$('export-journal').onclick=()=>{const blob=new Blob([`CAISIK / THE HIDDEN CITY\n\n${$('journal').value}`],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='caisik-fieldnotes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('clear-saved').onclick=()=>{const detail={persistent:true};window.dispatchEvent(new CustomEvent('caisik-clear-discoveries',{detail}));studied=[];const ok=remove('caisik-atlas-studies-v1');renderProgress();showPrinciple(current);$('clear-saved').textContent=ok&&detail.persistent?'Saved discoveries & study progress cleared':'Tab cleared; device storage unavailable';};

const artworks=[
['as-above-so-below','AS ABOVE / SO BELOW','72','22','SCALE / CORRESPONDENCE','A structure repeats at different scales. The resemblance begins a question; it does not settle it.'],
['transmute','TRANSMUTE','2','36','TRANSFORMATION / PROCESS','Original TRANSMUTE letterwork meets a reforming sculptural structure. Change needs a material practice.'],
['map-territory','THE MAP IS NOT THE TERRITORY','50','41','PERCEPTION / ORIENTATION','A compass and an urban threshold ask where a drawing ends and the lived city begins.'],
['know-thyself','KNOW THYSELF','5','71','ATTENTION / IDENTITY','Original KNOW THYSELF lettering and an open eye turn the act of looking back toward the observer.'],
['shadow-work','SHADOW WORK','39','32','SHADOW / REFLECTION','Inward eyes and a mirrored flame suggest the parts of a story we have not yet described. A creative reflection, not a clinical method.'],
['omerta-ego','OMERTÀ WITH THE EGO','33','38','MASK / SELF-AUTHORSHIP','An unmasking form and a mended crown ask which performance you are ready to put down.'],
['city-remembers','THE CITY REMEMBERS','48','69','MEMORY / URBAN LAYERS','Fragments of time become a fieldnote. Every new layer can carry the outline of an older one.'],
['underground-frequency','FREQUENCY OF THE UNDERGROUND','49','19','SOUND / COLLECTIVE EXPRESSION','Rooftop frequency meets a city in the groove. The city becomes a listening practice.']
];
$('gallery-grid').innerHTML=artworks.map((a,i)=>`<button class="gallery-card" data-art="${i}" aria-label="View ${a[1]}"><div class="gallery-image"><img src="/assets/atlas-art/${a[0]}.svg" alt="${a[1]} — original CAISIK artwork composition" width="600" height="600" loading="lazy"></div><h3>${a[1]}</h3><p>0${i+1} / ${a[4]}</p></button>`).join('');
let artTrigger=null;
$('gallery-grid').onclick=e=>{const b=e.target.closest('[data-art]');if(!b)return;artTrigger=b;const a=artworks[Number(b.dataset.art)];$('art-detail').innerHTML=`<img src="/assets/atlas-art/${a[0]}.svg" alt="${a[1]} — original CAISIK composition"><p class="eyebrow">${a[4]}</p><h2 id="art-dialog-title">${a[1]}</h2><p>${a[5]}</p><p>CAISIK archive remixed into an original transparent composition for The Hidden City. Contains original visual elements from the existing CAISIK collection; the title is an editorial caption.</p><a class="button primary" href="/assets/atlas-art/${a[0]}.svg" download="caisik-${a[0]}.svg">DOWNLOAD TRANSPARENT SVG <span>↓</span></a>`;$('art-dialog').showModal();};$('art-close').onclick=()=>$('art-dialog').close();$('art-dialog').addEventListener('close',()=>artTrigger?.focus());
$('photo-credits').onclick=async()=>{$('credits-list').textContent='Loading photography credits…';$('credits-dialog').showModal();try{const response=await fetch('/assets/paris/credits.json');if(!response.ok)throw new Error();const credits=await response.json();const entries=Array.isArray(credits)?credits:Object.values(credits);$('credits-list').innerHTML=entries.map(c=>`<div class="credit-entry"><strong>${esc(c.name||c.id||c.title)}</strong><p>${esc(c.author||'See source for author')} · ${esc(c.license||'See source for licence')}</p><a href="${esc(c.sourceUrl||c.sourceURL||c.source||'#')}" target="_blank" rel="noopener">Source & licence ↗</a></div>`).join('');}catch{$('credits-list').textContent='Credit data could not load. Consult the photo source links in the location profiles.';}};$('credits-close').onclick=()=>$('credits-dialog').close();
